"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[17014],{44255:e=>{e.exports=JSON.parse('{"id":"2026-06-22-8x8-resolve-documentation","date":"2026-06-22","products":["Resolve"],"product":"Resolve","channel":"","changeType":"Added","title":"8x8 Resolve documentation","excerpt":"8x8 Resolve is now a product area on the developer portal, with a full documentation set. Resolve is a critical communications platform that helps your organisation reach the right people instantly during an incident \u2014 sending targeted alerts across SMS, email, voice, WhatsApp, and mobile push, then tracking who acknow\u2026","hasArticle":true,"bodyHtml":"<p><strong>8x8 Resolve</strong> is now a product area on the developer portal, with a full documentation set. Resolve is a critical communications platform that helps your organisation reach the right people instantly during an incident \u2014 sending targeted alerts across SMS, email, voice, WhatsApp, and mobile push, then tracking who acknowledged and who needs help in real time.</p>\\n<h2>What you can do</h2>\\n<ul>\\n<li><strong>Create and send incidents</strong> \u2014 dispatch an alert to your entire organisation or a specific group in seconds, across multiple channels.</li>\\n<li><strong>Automate workflows</strong> \u2014 build scenarios that trigger on a schedule, branch on acknowledgement status, and escalate automatically.</li>\\n<li><strong>Sync your contacts</strong> \u2014 keep your recipient list current by connecting an HR system (Google Workspace, Microsoft Entra ID, Okta, or Workday).</li>\\n<li><strong>Monitor delivery</strong> \u2014 track delivery rates, acknowledgement rates, and response times from the dashboard.</li>\\n</ul>\\n<h2>The documentation set</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>Guide</th>\\n<th>What it covers</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td><a href=\\"/resolve/docs/overview\\">Overview</a></td>\\n<td>What Resolve is and how the pieces fit together.</td>\\n</tr>\\n<tr>\\n<td><a href=\\"/resolve/docs/dashboard\\">Dashboard</a></td>\\n<td>The home screen and your key metrics.</td>\\n</tr>\\n<tr>\\n<td><a href=\\"/resolve/docs/incidents\\">Incidents</a></td>\\n<td>Creating an incident and sending it across channels.</td>\\n</tr>\\n<tr>\\n<td><a href=\\"/resolve/docs/scenarios\\">Scenarios</a></td>\\n<td>Automated alert workflows with triggers, actions, and conditions.</td>\\n</tr>\\n<tr>\\n<td><a href=\\"/resolve/docs/contacts\\">Contacts</a></td>\\n<td>Managing recipients and connecting an HR system.</td>\\n</tr>\\n<tr>\\n<td><a href=\\"/resolve/docs/analytics\\">Analytics</a></td>\\n<td>Delivery, response rates, and channel effectiveness over time.</td>\\n</tr>\\n<tr>\\n<td><a href=\\"/resolve/docs/settings\\">Settings</a></td>\\n<td>Message templates, channels, and sender identities.</td>\\n</tr>\\n</tbody></table>\\n"}')}}]);